PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE resources (
  resource_id     TEXT PRIMARY KEY,
  identity        TEXT UNIQUE,
  canonical_url   TEXT NOT NULL UNIQUE,
  resource_type   TEXT NOT NULL,
  name            TEXT NOT NULL,
  description     TEXT,
  owner           TEXT,
  repo_name       TEXT,
  status          TEXT NOT NULL DEFAULT 'INDEXED',
  first_seen      TEXT NOT NULL,
  last_seen       TEXT NOT NULL,
  last_checked    TEXT,
  last_source_commit TEXT,
  quality_score   REAL,            -- P1：ResourceQualityEngine
  trust_level     TEXT,            -- P1：A/B/C/D/Quarantined/Rejected
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL
);
CREATE TABLE resource_sources (
  id               INTEGER PRIMARY KEY AUTOINCREMENT,
  resource_id      TEXT NOT NULL REFERENCES resources(resource_id),
  source_id        TEXT NOT NULL,
  source_repository TEXT NOT NULL,
  source_file      TEXT NOT NULL,
  source_section   TEXT NOT NULL,
  source_position  INTEGER,
  source_commit    TEXT NOT NULL,
  source_url       TEXT NOT NULL,           -- 原始 URL（含锚点/参数）
  first_seen       TEXT NOT NULL,
  last_seen        TEXT NOT NULL,
  UNIQUE(resource_id, source_section, source_url)
);
CREATE TABLE resource_categories (
  resource_id     TEXT NOT NULL REFERENCES resources(resource_id),
  category        TEXT NOT NULL,
  category_source TEXT NOT NULL,
  confidence      REAL NOT NULL DEFAULT 1.0,
  PRIMARY KEY (resource_id, category, category_source)
);
CREATE TABLE resource_versions (    -- P1 起逐资源版本；P0 记同步级版本
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  source_id     TEXT NOT NULL,
  commit_sha    TEXT NOT NULL,
  content_hash  TEXT NOT NULL,
  fetched_at    TEXT NOT NULL,
  resources_added   INTEGER,
  resources_updated INTEGER,
  resources_removed INTEGER,
  UNIQUE(source_id, commit_sha)
);
CREATE TABLE resource_relationships (  -- P2：与 Skills/Workflow/知识关联
  source_resource_id TEXT NOT NULL,
  target_entity_id   TEXT NOT NULL,
  relationship_type  TEXT NOT NULL,
  confidence         REAL DEFAULT 0.5,
  evidence           TEXT,
  created_at         TEXT,
  UNIQUE(source_resource_id, target_entity_id, relationship_type)
);
CREATE TABLE resource_reviews (        -- P1：审核记录
  resource_id   TEXT PRIMARY KEY REFERENCES resources(resource_id),
  review_status TEXT, reviewer TEXT, reviewed_at TEXT,
  technical_quality TEXT, maintenance_quality TEXT, license_status TEXT,
  security_status TEXT, decision TEXT, decision_reason TEXT
);
CREATE TABLE sync_state (
  source_id        TEXT PRIMARY KEY,
  upstream_repo    TEXT,
  default_branch   TEXT,
  last_commit_sha  TEXT,
  last_etag        TEXT,
  snapshot_hash    TEXT,
  source_license   TEXT,
  last_successful_sync TEXT,
  last_sync_status TEXT,
  last_error       TEXT
);
CREATE TABLE events (
  id     INTEGER PRIMARY KEY AUTOINCREMENT,
  ts     TEXT NOT NULL,
  actor  TEXT NOT NULL DEFAULT 'eri-p0',
  action TEXT NOT NULL,
  detail TEXT
);
CREATE TABLE github_metadata (
  resource_id     TEXT PRIMARY KEY REFERENCES resources(resource_id),
  repository_id   INTEGER, full_name TEXT, html_url TEXT,
  description     TEXT, homepage TEXT, visibility TEXT,
  archived        INTEGER, disabled INTEGER, fork INTEGER,
  parent_repository TEXT, default_branch TEXT,
  created_at      TEXT, updated_at TEXT, pushed_at TEXT,
  stargazers_count INTEGER, watchers_count INTEGER, forks_count INTEGER,
  open_issues_count INTEGER, language TEXT, topics TEXT,
  license_spdx_id TEXT, license_name TEXT, license_key TEXT,
  license_status  TEXT,      -- IDENTIFIED | FILE_UNIDENTIFIED | NO_LICENSE_FILE | AMBIGUOUS | UNKNOWN
  maintenance_status TEXT,   -- ACTIVE | LOW_ACTIVITY | STALE | ARCHIVED | DISABLED | UNAVAILABLE | UNKNOWN
  api_response_at TEXT, etag TEXT,
  fetch_status    TEXT,      -- ok | not_modified | gone | error
  fetch_error     TEXT,
  meta_updated_at TEXT
);
CREATE TABLE enrichment_state (
  resource_id TEXT PRIMARY KEY,
  last_attempt TEXT, attempts INTEGER DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'pending',  -- pending | done | failed | rate_limited
  note TEXT
);
CREATE TABLE d5_candidates (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  resource_a TEXT NOT NULL, resource_b TEXT NOT NULL,
  name_similarity REAL, description_similarity REAL, keyword_overlap REAL,
  category_overlap REAL, repository_relationship TEXT,
  decision TEXT NOT NULL,  -- POSSIBLE_DUPLICATE | RELATED_RESOURCE | FORK | MIRROR | DISTINCT | NEEDS_REVIEW
  score REAL, evidence TEXT, computed_at TEXT,
  UNIQUE(resource_a, resource_b)
);
CREATE TABLE quality_scores (
  resource_id TEXT PRIMARY KEY REFERENCES resources(resource_id),
  relevance REAL, reliability REAL, maintenance REAL, maturity REAL,
  complementarity REAL, license_clarity REAL, docs_testing REAL,
  final_score REAL, grade TEXT,           -- A | B | C | D
  adoption_blocked INTEGER DEFAULT 0,     -- 硬门槛：许可证不明等
  reasons TEXT,                           -- JSON 分项理由
  computed_at TEXT, engine_version TEXT
);
CREATE TABLE skill_mappings (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  resource_id TEXT NOT NULL REFERENCES resources(resource_id),
  target TEXT NOT NULL,                   -- skill:<name> 或 tool:<name> 或 workflow:<id>
  mapping_kind TEXT NOT NULL DEFAULT 'skill',
  mapping_status TEXT NOT NULL DEFAULT 'SUGGESTED',  -- SUGGESTED | REVIEWED | ADOPTED | REJECTED
  confidence REAL, match_basis TEXT,      -- 命中词证据
  capability_overlap TEXT, complementary TEXT,
  evidence TEXT, created_at TEXT, updated_at TEXT,
  UNIQUE(resource_id, target)
);
CREATE TABLE ai_usage_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  task_id TEXT, resource_ids TEXT, model TEXT,
  input_tokens INTEGER, output_tokens INTEGER,
  prompt_hash TEXT, content_hash TEXT, cached INTEGER,
  result TEXT, created_at TEXT
);
CREATE TABLE api_call_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  ts TEXT NOT NULL, resource_id TEXT, url TEXT,
  status INTEGER, etag_sent TEXT, etag_recv TEXT,
  rate_remaining INTEGER, note TEXT
);
CREATE TABLE resolver_queries (
  query_id TEXT PRIMARY KEY,
  task_id TEXT, created_at TEXT,
  input_json TEXT, result_ids TEXT,
  candidates INTEGER, filtered INTEGER, returned INTEGER, cache_hits INTEGER,
  elapsed_ms REAL, search_status TEXT
);
CREATE TABLE resource_usage (
  event_id INTEGER PRIMARY KEY AUTOINCREMENT,
  task_id TEXT, query_id TEXT, resource_id TEXT,
  event_type TEXT NOT NULL CHECK (event_type IN
    ('SEARCHED','RETURNED','OPENED','SELECTED','APPLIED','SUCCESSFUL','REJECTED')),
  workflow_id TEXT, skill_id TEXT,
  ts TEXT NOT NULL, result TEXT, reason TEXT
);
CREATE TABLE reader_cache (
  resource_id TEXT NOT NULL,
  kind TEXT NOT NULL,                    -- readme | license
  content_hash TEXT, byte_len INTEGER,
  commit_sha TEXT, etag TEXT,
  summary TEXT, summary_content_hash TEXT, summary_commit TEXT,
  path TEXT, fetched_at TEXT,
  PRIMARY KEY (resource_id, kind)
);
CREATE TABLE review_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  queue TEXT NOT NULL,                   -- d5 | mapping | license
  item_key TEXT NOT NULL,                -- 'a|b' / 'resource->target' / resource_id
  decision TEXT NOT NULL, confidence REAL,
  reason TEXT, reviewer TEXT DEFAULT 'eri-p2-rules',
  reviewed_at TEXT,
  UNIQUE(queue, item_key)
);
PRAGMA writable_schema=ON;
CREATE TABLE IF NOT EXISTS sqlite_sequence(name,seq);
DELETE FROM sqlite_sequence;
CREATE INDEX ix_sources_rid ON resource_sources(resource_id);
CREATE INDEX ix_sources_sid ON resource_sources(source_id, source_commit);
CREATE INDEX ix_d5_a ON d5_candidates(resource_a);
CREATE INDEX ix_d5_b ON d5_candidates(resource_b);
CREATE INDEX ix_map_rid ON skill_mappings(resource_id);
CREATE INDEX ix_usage_task ON resource_usage(task_id);
CREATE INDEX ix_usage_rid ON resource_usage(resource_id);
PRAGMA writable_schema=OFF;
COMMIT;
